INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000029',1,'APPROVED','PUBLISHED',
'{"objectives":["Use formal and informal language correctly in Kannada","Choose between neevu and neenu","Match verb endings to register"],"explanation":{"intro":"Polite language and formality covers the two main registers of Kannada — formal (using neevu, -iri endings) and informal (using neenu, -u endings) — and when to use each.","culturalNote":"Formality in Kannada: Kannada has a clear three-level system. (1) Formal/honorific (gaurava/maryade reetiya): neevu (you), -iri/-aare/-avaru endings. Used for: elders, strangers, teachers, bosses, customers. (2) Neutral/semi-formal: same as formal in many contexts. (3) Informal (samaana/adhama reetiya): neenu (you singular), -iya/-aane/-aaLe endings. Used for: close friends (mitraru), younger people, children, siblings. Do NOT use informal with strangers or elders — this is very rude. Social tip: when in doubt, always use formal. In Bengaluru, code-switching to English for uncertain situations is common. Gender-specific endings: 3rd person informal — avanu (he), avalu (she). Formal avoids this distinction: avaru works for all genders (very useful for politeness)."},"examples":[{"sentence":"Formal: Neevu elli hoguttiri? — Informal: Neenu elli hoguttiya?","english":"Formal: Where are you going? — Informal: Where are you going?"},{"sentence":"Neevu yenavaru? (formal) — Neenu yaavanu? (informal)","english":"Who are you? (formal) — Who are you? (informal)"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can choose the correct formality level in Kannada conversation."}}',
'{"items":[{"word":"neevu","translation":"you (formal/respectful)","transliteration":"neevu","pronunciation":"NEE-vu","example":"neevu banni"},{"word":"neenu","translation":"you (informal)","transliteration":"neenu","pronunciation":"NEE-nu","example":"neenu baa"},{"word":"banni","translation":"please come (formal imperative)","transliteration":"banni","pronunciation":"BAN-ni","example":"banni, kuu"},{"word":"baa","translation":"come (informal imperative)","transliteration":"baa","pronunciation":"baa","example":"baa, kuu"},{"word":"hogiri","translation":"please go (formal imperative)","transliteration":"hogiri","pronunciation":"ho-GI-ri","example":"hogiri, banni"},{"word":"hogu","translation":"go (informal imperative)","transliteration":"hogu","pronunciation":"HO-gu","example":"hogu, baa"}]}',
'{"title":"Formal vs informal Kannada — neevu/neenu, banni/baa, hogiri/hogu","pattern":"Formal (for elders/strangers): neevu (you), banni (come), hogiri (go), koodiri (sit), tiNNiri (eat), kudiri (drink). Informal (for friends/juniors): neenu (you), baa (come), hogu (go), kuu (sit), tinnu (eat), kudiyu (drink). Rule: when in doubt, use formal. 3rd person formal: avaru (he/she/they — respectful — gender-neutral).","explanation":"Register in Kannada: formal endings add -iri (imperative) or -aare (present 3rd). Informal ends in consonant or -u/-o. Examples: formal banni (come) vs informal baa. Formal hogiri (go) vs informal hogu. Formal koodiri (sit) vs informal kuu. Present tense: formal hoguttiri (you go) vs informal hoguttiya. Showing respect: using formal forms with anyone senior is never wrong. Code-switching: urban Bengalurians often switch to English when unsure of register. In Kannada films, heros/heroines speak informally to friends and formally to elders — observe this pattern.","examples":[{"sentence":"Doctor avaru banni enne nodiri (formal).","english":"Doctor, please come and examine me (formal)."},{"sentence":"Mitra, baa koTTe tinnoNa (informal).","english":"Friend, come let''s eat together (informal)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"neevu is the ___ form of you","options":["formal/respectful","informal","neutral","archaic"],"correctAnswer":"formal/respectful"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Where are you going? (formal)","options":["Neevu elli hoguttiri?","Neenu elli hoguttiya?","Avaru elli hoguttaare?","Neevu elli hogabahudu?"],"correctAnswer":"Neevu elli hoguttiri?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Doctor avaru ___ enne nodiri.","options":["banni","baa","hogiri","hogu"],"correctAnswer":"banni"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please come and sit (formal).","wordBankItems":["Banni","koodiri","."],"correctAnswer":"Banni koodiri ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hogiri is the ___ form of go","options":["formal imperative","informal imperative","question form","past form"],"correctAnswer":"formal imperative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002a',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe hobbies in more detail in Kannada","Use naanu X maaduttini yaakenendare for explaining why","Talk about how often and how long"],"explanation":{"intro":"Talking about hobbies in detail covers more elaborate descriptions — why you enjoy something, how often you do it, and how long you have been doing it.","culturalNote":"Hobby culture in Karnataka: traditional hobbies (classical music — Carnatic sangeetha, classical dance — Bharatanatyam, Kuchipudi, Mohiniyattam, traditional painting — Mysuru dasara art), modern hobbies (photography, video games, YouTube, trekking — Western Ghats trails). Birdwatching (pakshi nirrikshane) — Karnataka is a birder''s paradise — Western Ghats endemic species. Book reading: Kannada literature is rich — many people read Kannada novels. Cooking as hobby: food blogging, cooking shows. Traditional art: Channapatna toys (wooden lacquerware toys — UNESCO recognised Karnataka craft), Bidriware (silver inlay on zinc — from Bidar), Ilkal weaving, Navalgund durries (cotton rugs). Volunteering: many educated Bengalurians volunteer for education (Agastya Foundation, Pratham), rural development."},"examples":[{"sentence":"Naanu trekking maaduttini yaakenendare nature thumba ishtavagutte.","english":"I go trekking because I like nature very much."},{"sentence":"Naanu vaara vaara eradu sala badminton aaduttini.","english":"I play badminton twice a week."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my hobbies in detail — why I enjoy them and how often I do them."}}',
'{"items":[{"word":"sala","translation":"times/occasions","transliteration":"sala","pronunciation":"SA-la","example":"mooru sala"},{"word":"vaara vaara","translation":"every week/weekly","transliteration":"vaara vaara","pronunciation":"VAA-ra VAA-ra","example":"vaara vaara maaduttini"},{"word":"samaya","translation":"time/occasion","transliteration":"samaya","pronunciation":"SA-ma-ya","example":"bikaDi samaya"},{"word":"hecchaagi","translation":"more/increasingly","transliteration":"hecchaagi","pronunciation":"HECH-chaa-gi","example":"hecchaagi maadabeku"},{"word":"baraha","translation":"years (duration — varsha also used)","transliteration":"baraha","pronunciation":"BA-ra-ha","example":"mooru baraha"},{"word":"kellodi","translation":"listening (verbal noun of kelayu)","transliteration":"kellodi","pronunciation":"KEL-lo-di","example":"sangeetha kellodi"}]}',
'{"title":"Naanu X maaduttini yaakenendare Y — I do X because Y (reason for hobby)","pattern":"Naanu X maaduttini yaakenendare Y = I do X because Y. Yaakenendare = because (reason connector). Frequency: vaara vaara X sala (X times per week). Duration how long: X varsha/baraha inda (for X years — inda = since/for). Starting when: X vayassinda (since age X — vayassu = age).","explanation":"Detailed hobby description in Kannada: (1) What: naanu X maaduttini (I do X). (2) Why: yaakenendare Y (because Y). (3) How often: din alli X sala (X times a day), vaara vaara X sala (X times a week). (4) How long: X varsha inda maaduttini (I have been doing it for X years). (5) Learning: naanu X kalivuttiddeeni (I am learning X — kalivuttiddeeni = I am in the process of learning). Example: naanu mooru varsha inda photography maaduttini (I have been doing photography for 3 years). Intensifier with hobby: naakke X maaduvudu thumba ishtavagutte (I really like doing X — maaduvudu = the doing of = verbal noun).","examples":[{"sentence":"Naanu aidu varsha inda Carnatic sangeetha kalivuttiddeeni.","english":"I have been learning Carnatic music for 5 years."},{"sentence":"Naakke trekking maaduvudu thumba ishtavagutte yaakenendare hosa jagagaLannu nodabahudu.","english":"I really like trekking because I can see new places."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sala means?","options":["times/occasions","days","hours","weeks"],"correctAnswer":"times/occasions"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I go trekking because I like nature very much.","options":["Naanu trekking maaduttini yaakenendare nature thumba ishtavagutte.","Naanu photography maaduttini yaakenendare nature thumba ishtavagutte.","Naanu trekking maaduttini haagu nature thumba ishtavagutte.","Naanu trekking maaduttilla yaakenendare nature thumba ishtavagutte."],"correctAnswer":"Naanu trekking maaduttini yaakenendare nature thumba ishtavagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu vaara vaara eradu ___ badminton aaduttini.","options":["sala","dina","gante","vaara"],"correctAnswer":"sala"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have been learning Carnatic music for 5 years.","wordBankItems":["Naanu","aidu","varsha","inda","Carnatic","sangeetha","kalivuttiddeeni","."],"correctAnswer":"Naanu aidu varsha inda Carnatic sangeetha kalivuttiddeeni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"vaara vaara means?","options":["every week/weekly","every day","twice","sometimes"],"correctAnswer":"every week/weekly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002b',1,'APPROVED','PUBLISHED',
'{"objectives":["Shop for clothes in Kannada","Use ee saree/shirt naakke ishtavagutte for expressing preference","Understand size and fitting vocabulary"],"explanation":{"intro":"Shopping for clothes covers how to browse, try on, enquire about prices, and buy clothing in Kannada.","culturalNote":"Clothes shopping in Karnataka: traditional markets — Commercial Street (Bengaluru — historic shopping area), Chickpet (wholesale cloth — silk, cotton, synthetic), Gandhi Bazaar (South Bengaluru — traditional market). Silk sarees: Mysore Silk Factory (government-run — Mysuru) — premium Mysuru silk sarees. Craft silk: Dharwad silk, Ilkal saree (from Ilkal village in Bagalkot — famous for traditional weave). Mall shopping: UB City (luxury), Phoenix Marketcity, Orion Mall, Forum Mall (Bengaluru). Traditional clothing shops: Nalli Silks, Vijayalakshmi Silks. Size (size) = Western sizing used in modern stores. Traditional: small/medium/large. Fitting room (trial room). Discount (discount). Sale (sale). Tags: price tag. Exchange policy: exchange maadabaudu aa? (can this be exchanged?)."},"examples":[{"sentence":"Ee shirt naakke thumba ishtavagutte, aadare size sari aguttide aa?","english":"I really like this shirt, but will the size be right?"},{"sentence":"Ee shirt naakke size chikkadu, dodda beku.","english":"This shirt''s size is small for me, I need a bigger one."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can shop for clothes, express preferences, and ask about sizes in Kannada."}}',
'{"items":[{"word":"size","translation":"size","transliteration":"size","pronunciation":"saiz","example":"size sari aguttide"},{"word":"dodda","translation":"big/large","transliteration":"dodda","pronunciation":"DOD-da","example":"dodda size"},{"word":"chikka","translation":"small","transliteration":"chikka","pronunciation":"CHIK-ka","example":"chikka size"},{"word":"sari agutte","translation":"it fits/it is suitable","transliteration":"sari agutte","pronunciation":"SA-ri a-GUT-te","example":"size sari agutte"},{"word":"trial room","translation":"fitting/trial room","transliteration":"trial room","pronunciation":"TRY-al room","example":"trial room elli ide?"},{"word":"discount","translation":"discount","transliteration":"discount","pronunciation":"DIS-kount","example":"discount aguttide aa?"}]}',
'{"title":"Size sari aguttide aa? — Does the size fit? (clothes shopping)","pattern":"Size sari aguttide aa? = Does the size fit? Sari agutte = it is suitable/fitting. Chikkadu = it is small (for me). Doddadu = it is big (for me). Naakke sari aguttide = it fits me. Trial room elli? (where is the fitting room?). Exchange: ee batte exchange maadabahudu aa? (can this item be exchanged?).","explanation":"Clothes shopping in Kannada: (1) Liking: ee X naakke ishtavagutte (I like this X). (2) Price: eshtu aagutte? (how much is it?). (3) Size: ondu size dodda kodi (give me one size bigger). Size: chikka (small), madhyama (medium), dodda (large), thumba dodda (extra large). (4) Trial: trial room elli? (where is the fitting room?). (5) Fitting: sari aguttide (it fits), aguttilla (it doesn''t fit). (6) Colour: bere bana ide aa? (is there another colour? — bere = other/different). (7) Payment: card maaduttini / cash koDuttini (I''ll pay by card/cash).","examples":[{"sentence":"Ee saree alli bere bana ide aa?","english":"Is there another colour in this saree?"},{"sentence":"Naakke L size beku, M size sari aguttilla.","english":"I need size L, size M doesn''t fit."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sari agutte means?","options":["it fits/it is suitable","it is good","it is enough","it is right"],"correctAnswer":"it fits/it is suitable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I really like this shirt, but will the size be right?","options":["Ee shirt naakke thumba ishtavagutte, aadare size sari aguttide aa?","Ee saree naakke thumba ishtavagutte, aadare size sari aguttide aa?","Ee shirt nimage thumba ishtavagutte, aadare size sari aguttide aa?","Ee shirt naakke thakku ishtavagutte, aadare size sari aguttide aa?"],"correctAnswer":"Ee shirt naakke thumba ishtavagutte, aadare size sari aguttide aa?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke L size beku, M size sari ___ .","options":["aguttilla","agutte","aguttide","aayitu"],"correctAnswer":"aguttilla"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Is there another colour in this saree?","wordBankItems":["Ee","saree","alli","bere","bana","ide","aa","?"],"correctAnswer":"Ee saree alli bere bana ide aa ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"chikka means?","options":["small","big","medium","narrow"],"correctAnswer":"small"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002c',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate a railway station in Kannada","Use X tiket beku for buying tickets","Ask about train times and platforms"],"explanation":{"intro":"Railway station vocabulary covers how to buy tickets, ask about trains, and navigate station facilities in Kannada.","culturalNote":"Railway in Karnataka: SBC (Yeshvantpur/KSR Bengaluru City) and Bengaluru Cantonment are major stations. KSRTC connects by road, Indian Railways by rail. Trains: Rajdhani Express (Delhi-Bengaluru), Shatabdi (day trains), Duronto, local MEMU/DEMU trains. Karnataka''s famous train: Palace on Wheels (luxury tourist train). Hubballi (Hubli) is the major railway junction in North Karnataka. Mysuru-Bengaluru train: takes 2-2.5 hours. Class system: SL (Sleeper), 2AC, 3AC, 1AC (most expensive), CC (Chair Car for day trains). Booking: IRCTC (Indian Railway Catering and Tourism Corporation — official booking portal). Counter tickets also available at station. Station facilities: platform (platform), waiting room (waithu room), canteen (station canteen — chai and idli), cloakroom (luggage room). Reservation chart posted on coach. PNR (Passenger Name Record) — confirmation number."},"examples":[{"sentence":"Mysuru ge ondu tiket eshtu aagutte?","english":"How much is one ticket to Mysuru?"},{"sentence":"Bengaluru ge train yaava platform inda hoguttide?","english":"From which platform does the train to Bengaluru go?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate a railway station and buy train tickets in Kannada."}}',
'{"items":[{"word":"tiket","translation":"ticket","transliteration":"tiket","pronunciation":"TI-ket","example":"tiket kodi"},{"word":"platform","translation":"platform","transliteration":"platform","pronunciation":"PLAT-form","example":"platform number"},{"word":"train","translation":"train","transliteration":"train","pronunciation":"treyn","example":"train aagutte"},{"word":"seat","translation":"seat","transliteration":"seat","pronunciation":"seet","example":"seat ide aa?"},{"word":"yaava","translation":"which","transliteration":"yaava","pronunciation":"YAA-va","example":"yaava platform?"},{"word":"reserve","translation":"reservation/reserved","transliteration":"reserve","pronunciation":"ri-ZERV","example":"reserve tiket"}]}',
'{"title":"X ge tiket beku — I need a ticket to X (railway booking)","pattern":"Naakke X ge tiket beku = I need a ticket to X. Ge = to (directional). Tiket beku = need a ticket. Train enquiry: X ge train yaav time alli hoguttide? (at what time does the train to X go?). Platform: X train yaava platform inda hoguttide? (from which platform does the X train go?). Arrival: X train yaavaga baruttide? (when does the X train come?).","explanation":"Railway vocabulary in Kannada: tiket (ticket), platform (platform), seat (seat), coach (coach), reservation (reserve). Buying: naakke X ge ondu tiket beku (I need one ticket to X). Class: SL/2AC/3AC class tiket (SL/2AC/3AC class ticket). Return: X ge return tiket beku (I need a return ticket to X). Timing: X gante X nimisha alli hoguttide (it goes at X hours X minutes). Delayed: train late aagide (the train is late). Cancelled: train cancelled aagide (the train is cancelled). Announcement (announcement): announcement keLi (listen to the announcement — keLi = listen). Luggage: samaan (baggage/luggage).","examples":[{"sentence":"Naale beLigge Mysuru ge ondu SL tiket beku.","english":"I need one SL ticket to Mysuru for tomorrow morning."},{"sentence":"Train thumba late aagide, eshtu time aagutte?","english":"The train is very late, how much time will it take?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"tiket means?","options":["ticket","platform","seat","reservation"],"correctAnswer":"ticket"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"How much is one ticket to Mysuru?","options":["Mysuru ge ondu tiket eshtu aagutte?","Bengaluru ge ondu tiket eshtu aagutte?","Mysuru ge eradu tiket eshtu aagutte?","Mysuru ge ondu tiket ide aa?"],"correctAnswer":"Mysuru ge ondu tiket eshtu aagutte?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bengaluru ge train yaava ___ inda hoguttide?","options":["platform","seat","tiket","train"],"correctAnswer":"platform"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I need one SL ticket to Mysuru for tomorrow morning.","wordBankItems":["Naale","beLigge","Mysuru","ge","ondu","SL","tiket","beku","."],"correctAnswer":"Naale beLigge Mysuru ge ondu SL tiket beku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"yaava means?","options":["which","where","what","who"],"correctAnswer":"which"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002d',1,'APPROVED','PUBLISHED',
'{"objectives":["Invite and accept or decline invitations in Kannada","Use naale banni for inviting","Politely decline with gottilla, hogalaarenu"],"explanation":{"intro":"Invitations and refusals covers how to invite someone to an event, accept warmly, and decline politely in Kannada.","culturalNote":"Invitation culture in Karnataka: hospitality (athithi devo bhava — same principle as Hindi) means inviting guests for food is a duty. Formal invitations: shaadi/function invitation card (nimantrana patrika). Verbal invites: namma manege oota tinnoke banni (come to our house to eat — very common). Refusing an invitation: declining must be done politely and with a reason — a bare ''no'' is considered rude. Common polite refusals: namma maneyalli ondu kaaryakrama ide (there is a function at our house), naakke heltyaguvudu aguttide (I''m not feeling well — heltyaguvudu = not feeling well). Social obligation: in Karnataka, if you decline a food invitation three times, the host will insist four times — this is hospitality culture. Attending: bringing something (halasina haNNu = jackfruit, hannu = fruit, sweets) when invited is considered polite."},"examples":[{"sentence":"Naale namma manege oota tinnoke banni.","english":"Come to eat at our house tomorrow."},{"sentence":"Dhanyavadagalu, aadare naakke bere kaaryakrama ide.","english":"Thank you, but I have another event."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can invite people and politely accept or decline invitations in Kannada."}}',
'{"items":[{"word":"nimantrana","translation":"invitation","transliteration":"nimantrana","pronunciation":"ni-MAN-tra-na","example":"nimantrana kodi"},{"word":"banni","translation":"please come (formal invitation)","transliteration":"banni","pronunciation":"BAN-ni","example":"namma manege banni"},{"word":"kaaryakrama","translation":"event/function/programme","transliteration":"kaaryakrama","pronunciation":"kaar-ya-KRA-ma","example":"kaaryakrama ide"},{"word":"hogalaarenu","translation":"I cannot go/come (polite refusal)","transliteration":"hogalaarenu","pronunciation":"ho-ga-LAA-re-nu","example":"hogalaarenu, sorry"},{"word":"ilLu","translation":"let it be/okay (acceptance)","transliteration":"ilLu","pronunciation":"IL-lu","example":"ilLu, baruttini"},{"word":"zaroor","translation":"definitely/certainly (accepting)","transliteration":"zaroor","pronunciation":"za-ROOR","example":"zaroor baruttini"}]}',
'{"title":"Namma manege banni — Please come to our house (invitation in Kannada)","pattern":"Namma manege banni = Please come to our house. Banni = formal come (imperative). X tinnoke banni = come to eat X. Accepting: howdu, zaroor baruttini (yes, I will definitely come). Declining politely: dhanyavadagalu, aadare X ide haage hogalaarenu (thank you, but there is X so I cannot come). Hogalaarenu = I cannot come/go (polite negative).","explanation":"Invitation language in Kannada: banni (formal come), baa (informal come). Inviting for food: X tinnoke banni (come to eat X). Inviting for event: X kaaryakramake banni (come for X event). Accepting: zaroor baruttini (I will definitely come), howdu avashyavagi baruttini (yes I will certainly come — avashya = certainly). Declining: hogalaarenu (I cannot come — polite), naakke X ide (I have X), naakke health sari illaa (my health is not well). Semi-acceptance: try maaduttini (I will try). Checking: neevu baruttiri aa? (are you coming? — formal question).","examples":[{"sentence":"Shani vaara namma habba kaaryakramake neevu zaroor banni.","english":"You must definitely come to our festival event on Saturday."},{"sentence":"Naakke thumba beku itu, aadare bere commitment ide haage hogalaarenu.","english":"I really wanted to, but I have another commitment so I cannot come."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hogalaarenu means?","options":["I cannot come/go (polite refusal)","I don''t want to go","I went","I will go"],"correctAnswer":"I cannot come/go (polite refusal)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Come to eat at our house tomorrow.","options":["Naale namma manege oota tinnoke banni.","Inja namma manege oota tinnoke banni.","Naale namma angadige oota tinnoke banni.","Naale nimma manege oota tinnoke banni."],"correctAnswer":"Naale namma manege oota tinnoke banni."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dhanyavadagalu, aadare naakke bere ___ ide.","options":["kaaryakrama","nimantrana","banni","zaroor"],"correctAnswer":"kaaryakrama"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You must definitely come to our festival event on Saturday.","wordBankItems":["Shani","vaara","namma","habba","kaaryakramake","neevu","zaroor","banni","."],"correctAnswer":"Shani vaara namma habba kaaryakramake neevu zaroor banni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"zaroor means?","options":["definitely/certainly","maybe","please","perhaps"],"correctAnswer":"definitely/certainly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002e',1,'APPROVED','PUBLISHED',
'{"objectives":["Express opinions in Kannada","Use nanna abipraaya mein X for giving views","Agree and disagree politely"],"explanation":{"intro":"Opinions and agreement vocabulary covers how to share your view, agree enthusiastically, and disagree gently in Kannada.","culturalNote":"Opinion expression in Karnataka: intellectual and cultural discussions are common in Karnataka''s culture — debates about Kannada literature, culture, music are frequent. Kannada pride: Kannadigas are very proud of their language and culture — Rajyotsava Day (November 1) is celebrated with great passion. Opinion markers: nanna abipraaya (in my opinion — abipraaya = opinion/view). Political debates: discussions about politicians, development, language policy are common. Literary discussions: debates about Kuvempu, Poornachandra Tejaswi, U.R. Ananthamurthy (famous Kannada authors). Dissent: expressing disagreement respectfully is an art — nanna preety nageyillaa (I''m not too fond of it — gentle way to disagree). Strongly: naakke aaguttilla (I can''t accept/agree — very direct)."},"examples":[{"sentence":"Nanna abipraaya, ee yaojane thumba channa agutte.","english":"In my opinion, this plan is very good."},{"sentence":"Naanu nimage sahmat, aadare ondu vishaya iddhe.","english":"I agree with you, but there is one thing."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can share opinions and agree or disagree politely in Kannada."}}',
'{"items":[{"word":"abipraaya","translation":"opinion/view","transliteration":"abipraaya","pronunciation":"a-bi-PRAA-ya","example":"nanna abipraaya"},{"word":"sahmat","translation":"agree/in agreement","transliteration":"sahmat","pronunciation":"SAH-mat","example":"naanu sahmat"},{"word":"asahmat","translation":"disagree","transliteration":"asahmat","pronunciation":"a-SAH-mat","example":"naanu asahmat"},{"word":"sari","translation":"right/correct/okay","transliteration":"sari","pronunciation":"SA-ri","example":"sari aagutte"},{"word":"galata","translation":"wrong/mistake","transliteration":"galata","pronunciation":"ga-LA-ta","example":"ee galata"},{"word":"nanna preety","translation":"my preference/I prefer (lit. my love)","transliteration":"nanna preety","pronunciation":"NAN-na PREE-ti","example":"nanna preety nageyillaa"}]}',
'{"title":"Nanna abipraaya, X — In my opinion, X (opinion expression in Kannada)","pattern":"Nanna abipraaya, X = In my opinion, X. Nanna abipraaya mein = in my opinion (mein = in — Urdu borrowed but used). Naakke X aguttide = it seems X to me. Agreeing: naanu sahmat (I agree), howdu sari (yes, correct). Disagreeing: naanu asahmat (I disagree), naakke aaguttilla (I cannot accept), aadare X ide (but there is X).","explanation":"Opinion in Kannada: nanna abipraaya (my opinion — from Sanskrit abhipraaya = expression towards). Naakke X aguttide (to me it seems X). Naanu X anta nambuttini (I believe X — nambuttini = I believe). Agreeing: sahmat (agree — from Arabic/Urdu), howdu sari (yes, that''s right). Enthusiastically: naanu poortiyaagi sahmat (I completely agree — poortiyaagi = completely). Disagreeing: asahmat (disagree), adu sari alla (that is not right), naanu bere tara nambuttini (I believe differently). Soft disagreement: nanna preety nageyillaa (I''m not too fond of it — very gentle, face-saving disagreement).","examples":[{"sentence":"Naakke ee decision sari anta aguttide.","english":"To me this decision seems right."},{"sentence":"Naanu poortiyaagi sahmat, ee yaojane adbhutavagutte.","english":"I completely agree, this plan is wonderful."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"abipraaya means?","options":["opinion/view","feeling","preference","thought"],"correctAnswer":"opinion/view"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my opinion, this plan is very good.","options":["Nanna abipraaya, ee yaojane thumba channa agutte.","Nanna abipraaya, aa yaojane thumba channa agutte.","Nimma abipraaya, ee yaojane thumba channa agutte.","Nanna abipraaya, ee yaojane thakku channa agutte."],"correctAnswer":"Nanna abipraaya, ee yaojane thumba channa agutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu nimage ___ , aadare ondu vishaya iddhe.","options":["sahmat","asahmat","galata","sari"],"correctAnswer":"sahmat"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I completely agree, this plan is wonderful.","wordBankItems":["Naanu","poortiyaagi","sahmat",",","ee","yaojane","adbhutavagutte","."],"correctAnswer":"Naanu poortiyaagi sahmat , ee yaojane adbhutavagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sari means?","options":["right/correct/okay","wrong","maybe","equal"],"correctAnswer":"right/correct/okay"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000002f',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a day out in Kannada","Narrate a sequence of events using past tense","Use phir-type connectors for sequence"],"explanation":{"intro":"Describing a day out covers how to narrate a sequence of events in the past — what you did, where you went, and what you saw during a trip or outing.","culturalNote":"Day trips from Bengaluru: Nandi Hills (60km — sunrise trek — ancient hilltop fort), Mysuru (140km — Mysuru Palace, zoo, silk, Chamundi Hills), Coorg (250km — coffee estates, waterfalls, trekking), Shivanasamudra Falls (130km — twin falls on River Cauvery), Hampi (340km — overnight — UNESCO ruins), Sakleshpur (200km — coffee estates, train journey through Western Ghats), Skandagiri (70km — night trek, sunrise). Weekend getaways are extremely popular among Bengaluru''s young professionals. Road trips: NH-48 Bengaluru-Mysuru highway (upgraded to 10-lane expressway). Popular spots on the way: Ramanagaram (Silk City, Ramsay Rockies filming location for Sholay), Channapatna (toy town — lacquerware toys)."},"examples":[{"sentence":"Ninne naanu Nandi Hills ge hode haagu sunrise nodide.","english":"Yesterday I went to Nandi Hills and saw the sunrise."},{"sentence":"Prathama Mysuru Palace nodide, nantara market ge hode.","english":"First I saw Mysuru Palace, then I went to the market."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe a day out and narrate a sequence of events in Kannada."}}',
'{"items":[{"word":"prathama","translation":"first","transliteration":"prathama","pronunciation":"PRA-tha-ma","example":"prathama hogona"},{"word":"nantara","translation":"then/after that","transliteration":"nantara","pronunciation":"NAN-ta-ra","example":"nantara nodide"},{"word":"kaDeyalli","translation":"at the end/finally","transliteration":"kaDeyalli","pronunciation":"ka-De-YAL-li","example":"kaDeyalli tirugida"},{"word":"tirugida","translation":"returned/came back","transliteration":"tirugida","pronunciation":"ti-RU-gi-da","example":"manege tirugida"},{"word":"samayada","translation":"enjoyable/good time (verbal noun)","transliteration":"samayada","pronunciation":"sa-MA-ya-da","example":"channa samaya"},{"word":"thakasele","translation":"tired (feeling tired after activity)","transliteration":"thakasele","pronunciation":"tha-KA-se-le","example":"thumba thakasele"}]}',
'{"title":"Prathama X, nantara Y, kaDeyalli Z — sequence narration in Kannada","pattern":"Prathama X hode, nantara Y nodide, kaDeyalli Z tirugida = First I went to X, then I saw Y, finally I returned Z. Prathama = first. Nantara = then/after. KaDeyalli = at the end/finally. Past tense: hode (went), nodide (saw), tinde (ate), kudide (drank), maadide (did), tirugida (returned).","explanation":"Sequence narration in Kannada: prathama (first), nantara (then/after), avara nantara (after that — more formal), kaDeyalli (at the end/finally). Past tense review: hode (went), bande (came), nodide (saw/visited), tinde (ate), kudide (drank), odide (read), tirugida (returned — tirugi + da). Describing enjoyment: thumba channa time kaalida (I spent a very good time — kaalida = spent). Tiredness: thumba thakasele (very tired — but worth it!). Future planning: naale matte hogona (let''s go again tomorrow).","examples":[{"sentence":"Naanu Hampi ge hode — prathama ruins nodide, nantara oota tinde, kaDeyalli sunset nodide.","english":"I went to Hampi — first I saw the ruins, then I ate food, finally I saw the sunset."},{"sentence":"Thumba channa trip aayitu, aadare thumba thakasele aayitu.","english":"It was a very good trip, but I became very tired."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"prathama means?","options":["first","then","finally","last"],"correctAnswer":"first"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Yesterday I went to Nandi Hills and saw the sunrise.","options":["Ninne naanu Nandi Hills ge hode haagu sunrise nodide.","Inja naanu Nandi Hills ge hode haagu sunrise nodide.","Ninne naanu Nandi Hills ge bande haagu sunrise nodide.","Ninne avanu Nandi Hills ge hoda haagu sunrise nodi."],"correctAnswer":"Ninne naanu Nandi Hills ge hode haagu sunrise nodide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Thumba channa trip aayitu, aadare thumba ___ aayitu.","options":["thakasele","santosha","samayada","prathama"],"correctAnswer":"thakasele"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: First I saw Mysuru Palace, then I went to the market.","wordBankItems":["Prathama","Mysuru","Palace","nodide",",","nantara","market","ge","hode","."],"correctAnswer":"Prathama Mysuru Palace nodide , nantara market ge hode ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"tirugida means?","options":["returned/came back","went","arrived","left"],"correctAnswer":"returned/came back"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000030',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe Karnataka''s geography in Kannada","Name regions and landmarks using Kannada","Talk about distances and directions"],"explanation":{"intro":"Karnataka geography covers the state''s major regions, rivers, mountains, and landmarks using Kannada vocabulary.","culturalNote":"Karnataka geography: Area: 191,791 km² — 8th largest state. Population: ~67 million. Districts: 31 districts. Regions: (1) Coastal Karnataka (Karavali) — Arabian Sea coast — Mangaluru, Udupi, Karwar. (2) Malnad — Western Ghats hill region — Shivamogga, Chikmagalur, Hassan, Kodagu. (3) Mysuru region (Old Mysore) — southern plateau — Mysuru, Chamarajanagara, Mandya. (4) Bengaluru region — central plateau — IT hub. (5) North Karnataka — Dharwad, Hubballi, Kalaburagi (Gulbarga) — drier, historical. Rivers: Kaveri (Cauvery — Krishna Sagar Dam — major river), Tungabhadra (Hampi — flows by ruins), Krishna, Sharavathi (Jog Falls). Mountains: Western Ghats (Sahyadri — Kudremukh peak 1894m — Karnataka''s second highest), Nandi Hills (1481m), Biligirirangana Hills (B.R. Hills). Languages: Kannada (official), Kodava (Coorg), Tulu (coastal), Konkani (Karwar)."},"examples":[{"sentence":"Karnataka alli moovattu ondu jilegalu idhe.","english":"In Karnataka there are 31 districts."},{"sentence":"Kaveri naadi Kodagu jileyalli huttuttade haagu Karnataka-Tamil Nadu inda hoguttade.","english":"The Kaveri river originates in Kodagu district and flows through Karnataka and Tamil Nadu."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe Karnataka''s geography and major features in Kannada."}}',
'{"items":[{"word":"jiley","translation":"district","transliteration":"jiley","pronunciation":"ji-LE","example":"Mysuru jiley"},{"word":"naadi","translation":"river","transliteration":"naadi","pronunciation":"NAA-di","example":"Kaveri naadi"},{"word":"betta","translation":"hill/mountain","transliteration":"betta","pronunciation":"BET-ta","example":"Nandi betta"},{"word":"kaadu","translation":"forest/jungle","transliteration":"kaadu","pronunciation":"KAA-du","example":"kaadu ide"},{"word":"kadal","translation":"sea/ocean","transliteration":"kadal","pronunciation":"ka-DAL","example":"arabian kadal"},{"word":"kere","translation":"lake/tank (traditional)","transliteration":"kere","pronunciation":"KE-re","example":"kere hattira"}]}',
'{"title":"Karnataka geography vocabulary — naadi, betta, jiley, kaadu","pattern":"X naadi = X river. X betta = X hill. X jiley = X district. X kaadu = X forest. Location: X alli ide (is in X). Flow: X inda Y ge hoguttade (it goes from X to Y — hoguttade = it goes, 3rd neuter). Origin: X alli huttuttade (it originates in X — huttuttade = it is born/originates, 3rd neuter).","explanation":"Karnataka geography in Kannada: natural features use specific words. River: naadi (naadi = river). Hill: betta (betta = hill/small mountain). Mountain: parvata (mountain — more formal). Forest: kaadu (jungle/forest). Lake: kere (traditional tank/lake — karnataka has thousands of ancient tanks). Sea: kadal (sea/ocean). District: jiley (from English district via local pronunciation). Compass: uttara (north), dakshina (south), paschima (west), poorva (east). Located: X uttara bhagadalli ide (X is in the northern part). Famous combination: X ge Y ge maddhye ide (X is between Y and Y).","examples":[{"sentence":"Kabini naadi Nagarhole kaadu alli hoguttade.","english":"The Kabini river flows through the Nagarhole forest."},{"sentence":"Chikmagalur jilleya Western Ghats alli kaapi bele maaduttaare.","english":"They cultivate coffee in the Western Ghats of Chikmagalur district."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"naadi means?","options":["river","lake","hill","sea"],"correctAnswer":"river"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In Karnataka there are 31 districts.","options":["Karnataka alli moovattu ondu jilegalu idhe.","Karnataka alli moovattu eradu jilegalu idhe.","Karnataka alli ippattu jilegalu idhe.","Bengaluru alli moovattu ondu jilegalu idhe."],"correctAnswer":"Karnataka alli moovattu ondu jilegalu idhe."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kabini naadi Nagarhole ___ alli hoguttade.","options":["kaadu","betta","naadi","kere"],"correctAnswer":"kaadu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The Kaveri river originates in Kodagu district.","wordBankItems":["Kaveri","naadi","Kodagu","jileyalli","huttuttade","."],"correctAnswer":"Kaveri naadi Kodagu jileyalli huttuttade ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"betta means?","options":["hill/mountain","forest","river","valley"],"correctAnswer":"hill/mountain"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000031',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about work and career in Kannada","Use naanu X company alli Y kaela maaduttini","Discuss career goals and ambitions"],"explanation":{"intro":"Work and career vocabulary covers job titles, workplace talk, career aspirations, and how to describe your professional life in Kannada.","culturalNote":"Work culture in Karnataka: Bengaluru is India''s Silicon Valley — ITES (IT Enabled Services), BPO (Business Process Outsourcing), startups (unicorn = startup valued over $1 billion — India has many unicorns headquartered in Bengaluru: Flipkart, Zomato, Swiggy, Byju''s, Razorpay, Freshworks, etc.). Work-life balance: young professionals in Bengaluru face long hours but benefit from good salaries. IIT/IIM graduates highly sought after. Work aspirations: government job (sarkari kaela — stable, respected, pension), private sector (private company — high salary, less security), self-employment (swarozhgaara — own business). Agriculture: farming (krushi) is Karnataka''s backbone — many IT workers have farming roots. Startups: startup maadu (to start a startup — maadu = to do)."},"examples":[{"sentence":"Naanu ondu IT startup alli product manager kaela maaduttini.","english":"I work as a product manager at an IT startup."},{"sentence":"Nanna kaela guri yaakenendare nanna swarozhgaara shurumaaD beku.","english":"My career goal is because I want to start my own business."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about my job, workplace, and career aspirations in Kannada."}}',
'{"items":[{"word":"guri","translation":"goal/aim/target","transliteration":"guri","pronunciation":"GU-ri","example":"nanna guri"},{"word":"anubhava","translation":"experience","transliteration":"anubhava","pronunciation":"a-NU-bha-va","example":"X anubhava ide"},{"word":"sambhavana","translation":"salary/income","transliteration":"sambhavana","pronunciation":"sam-BHA-va-na","example":"channa sambhavana"},{"word":"shuru","translation":"start/beginning","transliteration":"shuru","pronunciation":"SHU-ru","example":"shuru maadu"},{"word":"swarozhgaara","translation":"self-employment/own business","transliteration":"swarozhgaara","pronunciation":"swa-rozh-GAA-ra","example":"swarozhgaara maadu"},{"word":"promotion","translation":"promotion","transliteration":"promotion","pronunciation":"pro-MO-shun","example":"promotion aayitu"}]}',
'{"title":"Naanu X alli Y kaela maaduttini — I work as Y at X (detailed job description)","pattern":"Naanu X alli Y kaela maaduttini = I work as Y at X. X = company/workplace. Y = job title. Alli = at/in. Kaela maaduttini = I work (habitual). Career goal: nanna guri X maaduvudu (my goal is to do X). Experience: nanna X anubhava ide (I have X experience).","explanation":"Career vocabulary in Kannada: kaela (work), sambhavana (salary), anubhava (experience), promotion (promotion), team (team), project (project), deadline (deadline), meeting (meeting). Job search: kaela haadutte iddini (I am looking for a job — haadutte iddini = I am searching). Interview: interview aayitu (the interview happened). Got the job: kaela sikkitu (the job was received — sikkitu = was obtained/gotten). Lost job: kaela hogitu (the job went — hogitu = went away). Ambition: nanna swapna X maaduvudu (my dream is to do X). Work-life: kaela-manassu balansu (work-life balance — using English-Kannada mix as common in urban speech).","examples":[{"sentence":"Naanu aidu varsha inda IT alli kaela maaduttini haagu abhi manager position alli iddini.","english":"I have been working in IT for 5 years and am now in a manager position."},{"sentence":"Nanna guri ondu tech startup shuru maaduvudu.","english":"My goal is to start a tech startup."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"guri means?","options":["goal/aim/target","start","experience","salary"],"correctAnswer":"goal/aim/target"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I work as a product manager at an IT startup.","options":["Naanu ondu IT startup alli product manager kaela maaduttini.","Naanu ondu IT company alli product manager kaela maaduttini.","Naanu eradu IT startup alli product manager kaela maaduttini.","Avanu ondu IT startup alli product manager kaela maaduttaane."],"correctAnswer":"Naanu ondu IT startup alli product manager kaela maaduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna guri ondu tech startup ___ maaduvudu.","options":["shuru","sambhavana","anubhava","guri"],"correctAnswer":"shuru"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My goal is to start a tech startup.","wordBankItems":["Nanna","guri","ondu","tech","startup","shuru","maaduvudu","."],"correctAnswer":"Nanna guri ondu tech startup shuru maaduvudu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"anubhava means?","options":["experience","knowledge","skill","talent"],"correctAnswer":"experience"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000032',1,'APPROVED','PUBLISHED',
'{"objectives":["Consolidate Kannada A1 conversation skills","Have a complete A1 conversation in Kannada","Review all major A1 topics and patterns"],"explanation":{"intro":"A1 Milestone conversation review consolidates all topics from lessons 1-49 with a focus on holding a complete, natural basic conversation in Kannada.","culturalNote":"Completing Kannada A1: you can now greet people (Namaskara), introduce yourself (naanu X iddini), describe your family and home, navigate markets and restaurants (eshtu aagutte? kodi), use transport (bus/auto/train alli), ask for directions (eliide?), describe your daily routine (pratidinaa X maaduttini), talk about Karnataka''s culture and geography, express emotions (naakke X aagutte), discuss festivals (habba), talk about work and hobbies, and hold basic conversations. Grammar mastered: habitual present (-uttini), past (-de/-ida forms), directional (X ge), locative (X alli), dative (naakke/nimage), liking (ishtavagutte), beku (need/want), dayavittu (please), howdu/illa (yes/no). Cultural knowledge: Bengaluru, Mysuru, Hampi, Coorg, Dasara, Ugaadi, filter kaapi, bisi bele bath. Congratulations! Ab Kannada A2 ge hogona!"},"examples":[{"sentence":"Namaskara! Naanu Priya, naanu Bengaluruinda. Neevu yaaru?","english":"Hello! I am Priya, I am from Bengaluru. Who are you?"},{"sentence":"Naakke Kannada kelarattitu, eedannu naanu A1 mattadalli thumba kali maadide.","english":"I wanted to learn Kannada, and now I have learned a lot at the A1 level."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed Kannada A1 and can hold basic conversations on all everyday topics."}}',
'{"items":[{"word":"kali","translation":"to learn (stem)","transliteration":"kali","pronunciation":"KA-li","example":"Kannada kali"},{"word":"Namaskara","translation":"Hello/Namaste (universal greeting)","transliteration":"Namaskara","pronunciation":"na-mas-KA-ra","example":"Namaskara, hege iddiri?"},{"word":"channa","translation":"good/nice/beautiful","transliteration":"channa","pronunciation":"CHAN-na","example":"thumba channa"},{"word":"hogona","translation":"let''s go","transliteration":"hogona","pronunciation":"ho-GO-na","example":"hogona, baa"},{"word":"dhanyavadagalu","translation":"thank you (formal)","transliteration":"dhanyavadagalu","pronunciation":"dhan-ya-VA-da-ga-lu","example":"dhanyavadagalu nimge"},{"word":"mattaadi","translation":"talk again/speak again","transliteration":"mattaadi","pronunciation":"mat-TAA-di","example":"mattaadi baruttini"}]}',
'{"title":"Complete A1 Kannada conversation — all 10 patterns in one exchange","pattern":"A complete A1 conversation includes: (1) Namaskara (greeting). (2) Naanu X iddini (introduction). (3) Neevu yaaru? (asking who). (4) X alli kaela maaduttini (work). (5) Naakke X ishtavagutte (hobbies/likes). (6) Eshtu aagutte? (shopping). (7) X ge hoguttini (directions/plans). (8) Howdu/illa (yes/no). (9) Dayavittu/dhanyavadagalu (please/thank you). (10) Mattaadi baruttini (farewell).","explanation":"Complete A1 Kannada conversation: start with Namaskara + hege iddiri? (formal greeting). Introduce: naanu X, naanu Y jileyinda (I am X, I am from Y district). Work: naanu X alli kaela maaduttini. Hobbies: naakke X maaduvudu ishtavagutte. Plans: naanu X ge hoguttini. Farewell: thumba channa aayitu, mattaadi banni (it was very good, please come again). The A2 level will build on this foundation — compound sentences, reported speech, conditional sentences, richer vocabulary, and deeper cultural understanding of Karnataka.","examples":[{"sentence":"Namaskara! Naanu Arjun, naanu Mysuru jileyinda. Neevu?","english":"Hello! I am Arjun, I am from Mysuru district. You?"},{"sentence":"Thumba channa aaythu nimage nodide. Mattaadi sigoNa.","english":"It was very nice to meet you. Let''s meet again."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kali means?","options":["to learn","to teach","to study","to read"],"correctAnswer":"to learn"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello! I am Priya, I am from Bengaluru. Who are you?","options":["Namaskara! Naanu Priya, naanu Bengaluruinda. Neevu yaaru?","Namaskara! Naanu Priya, naanu Bengaluruinda. Avaru yaaru?","Namaskara! Naanu Priya, naanu Mysurinda. Neevu yaaru?","Namaskara! Avaru Priya, naanu Bengaluruinda. Neevu yaaru?"],"correctAnswer":"Namaskara! Naanu Priya, naanu Bengaluruinda. Neevu yaaru?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Thumba channa aaythu nimage nodide. Mattaadi ___ .","options":["sigoNa","banni","hogona","maadide"],"correctAnswer":"sigoNa"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Hello! I am Arjun, I am from Mysuru district.","wordBankItems":["Namaskara","!","Naanu","Arjun",",","naanu","Mysuru","jileyinda","."],"correctAnswer":"Namaskara ! Naanu Arjun , naanu Mysuru jileyinda ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"dhanyavadagalu means?","options":["thank you (formal)","sorry","hello","please"],"correctAnswer":"thank you (formal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

